/** The run settings changed (a run is added with defaults when there was none). */
export function updateRun(diagram: ProcessFlowDiagram, patch: Partial<FlowRun>): ProcessFlowDiagram {
  const run = { duration: diagram.run?.duration ?? defaultRunDuration(flowTimeUnit(diagram)), ...diagram.run, ...patch };
  return { ...diagram, run: withoutEmpty(run) };
}

/** A sensible run length when the file has none: a working day in the flow's unit. */
export function defaultRunDuration(unit: TimeUnit): number {
  return { seconds: 8 * 3600, minutes: 8 * 60, hours: 8 * 5, days: 60 }[unit];
}

/** Optional values cleared in the editor are left out of the file. */
function withoutEmpty<T extends object>(value: T): T {
  return Object.fromEntries(Object.entries(value).filter(([, entry]) => entry !== undefined && entry !== '')) as T;
}
